            if (err) {
                reject(err);
            } else {
                resolve(filedata);
                console.log(filedata);
            }
        });
    });
}
</code></pre>

<p>However, if you're using Node 10 or above, importing <code>require('fs').promises</code> lets you use its methods as typical async functions:</p>

<pre><code>const fs = require('fs').promises;

module.exports = {
    foo: async () =&gt; {
        const filedata = await fs.readFile('./scripts/pairs.json');
        console.log(filedata);
        return filedata;
    }
}
</code></pre>

